from pathlib import Path
import json,re

HOME=Path.home()
STATE=HOME/".local/state/prediction-project-executor"/"DEV-PRED-A2Z-DIRECT-SOL-REGRESSION-N1E36-20261007.json"
CAMPAIGN=HOME/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
ASTRA="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
PROPOSAL="A2Z-V4-SOL-PROPOSAL-DIRECT-20261007-R4P2"
OLD_SOL="A2Z-V4-SOL-BUILD-20261007-R4"

def load(p): return json.loads(p.read_text(encoding="utf-8"))

# --- Assert persisted N1E36 result, no test execution here ---
if not STATE.is_file():
    raise RuntimeError("N1E36_STATE_MISSING")
o=load(STATE)
blob=json.dumps(o,ensure_ascii=False,sort_keys=True)
if str(o.get("status") or "").upper()!="PASS":
    raise RuntimeError("N1E36_STATUS_NOT_PASS:"+str(o.get("status")))
if "tests/model_execution/test_direct_sol_chat.py" not in blob or "unittest" not in blob:
    raise RuntimeError("N1E36_TARGET_TEST_NOT_RECORDED")
rcs=[]
def walk(v):
    if isinstance(v,dict):
        for k,x in v.items():
            if k in {"rc","returncode","exit_code"} and isinstance(x,int):
                rcs.append(x)
            walk(x)
    elif isinstance(v,list):
        for x in v: walk(x)
walk(o)
if not rcs:
    raise RuntimeError("N1E36_NO_EXPLICIT_RC_EVIDENCE")
if any(x!=0 for x in rcs):
    raise RuntimeError("N1E36_NONZERO_RC:"+repr(rcs))
print("N1E36_ASSERT=PASS")
print("N1E36_RCS="+json.dumps(rcs))

# --- Exact request binding ---
req=CAMPAIGN/"requests"/(ASTRA+".json")
if not req.is_file():
    raise RuntimeError("ASTRA_REQUEST_MISSING")
r=load(req)
if r.get("task_id")!=ASTRA:
    raise RuntimeError("ASTRA_TASK_ID_MISMATCH")
if r.get("phase")!="ASTRA_PREBUILD":
    raise RuntimeError("ASTRA_PHASE_MISMATCH:"+str(r.get("phase")))
if r.get("model_policy")!="ASTRA_EXACT":
    raise RuntimeError("ASTRA_POLICY_MISMATCH:"+str(r.get("model_policy")))
rb=json.dumps(r,ensure_ascii=False,sort_keys=True)
if PROPOSAL not in rb:
    raise RuntimeError("ASTRA_PROPOSAL_BINDING_MISSING")
if OLD_SOL in rb:
    raise RuntimeError("ASTRA_REQUEST_CONTAINS_OLD_SOL")
if re.search(r"codex.{0,80}resume|resume.{0,80}codex",rb,re.I):
    raise RuntimeError("ASTRA_REQUEST_HAS_RESUME_THREAD")
print("ASTRA_REQUEST_ASSERT=PASS")

# --- No existing result or duplicate run ---
res=CAMPAIGN/"model_results"/(ASTRA+".json")
if res.is_file():
    raise RuntimeError("ASTRA_RESULT_ALREADY_EXISTS")
runs=CAMPAIGN/"models/runs"
astra_runs=sorted([p.name for p in runs.glob(ASTRA+"*") if p.is_dir()]) if runs.exists() else []
if astra_runs:
    raise RuntimeError("ASTRA_RUN_ALREADY_EXISTS:"+",".join(astra_runs))
print("ASTRA_DUPLICATE_ASSERT=PASS")

# --- Queue/control metadata: any object mentioning requested Astra must not mix old SOL or resume ---
models=CAMPAIGN/"models"
hits=0
for p in sorted(models.rglob("*")) if models.exists() else []:
    if not p.is_file():
        continue
    name=p.name.lower()
    if not (name in {"state.json","queue.json","task.json","worker.json","request.json"} or "queue" in name or "state" in name):
        continue
    try:
        txt=p.read_text(encoding="utf-8")
    except Exception:
        continue
    if ASTRA not in txt:
        continue
    hits+=1
    if OLD_SOL in txt:
        raise RuntimeError("ASTRA_QUEUE_MIXES_OLD_SOL:"+str(p))
    if re.search(r"codex.{0,120}resume|resume.{0,120}codex",txt,re.I|re.S):
        raise RuntimeError("ASTRA_QUEUE_HAS_RESUME:"+str(p))
print("ASTRA_QUEUE_HITS="+str(hits))
print("PREBUILD_BINDING_ASSERT=PASS")
